package com.yeyamo_mobile.api.graph_service.interfaces;
import com.yeyamo_mobile.api.graph_service.application.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1")public class CultureGraphController{private final CultureGraphQueryService query;private final GraphRebuildService rebuild;public CultureGraphController(CultureGraphQueryService q,GraphRebuildService r){query=q;rebuild=r;}
 @GetMapping("/culture-graph/artworks/{id}/related")public List<CultureGraphQueryService.Relation>artwork(@PathVariable String id,@RequestParam(defaultValue="50")int limit){return query.related("Artwork",id,limit);}@GetMapping("/culture-graph/cultures/{id}/explore")public List<CultureGraphQueryService.Relation>culture(@PathVariable String id,@RequestParam(defaultValue="50")int limit){return query.related("Culture",id,limit);}@GetMapping("/culture-graph/languages/{code}/related")public List<CultureGraphQueryService.Relation>language(@PathVariable String code,@RequestParam(defaultValue="50")int limit){return query.related("Language",code,limit);}@GetMapping("/culture-graph/artisans/{id}/related")public List<CultureGraphQueryService.Relation>artisan(@PathVariable String id,@RequestParam(defaultValue="50")int limit){return query.related("Artisan",id,limit);}@GetMapping("/culture-graph/places/{id}/culture")public List<CultureGraphQueryService.Relation>place(@PathVariable String id,@RequestParam(defaultValue="50")int limit){return query.exploreCulture(id,limit);}@GetMapping("/culture-graph/discover")public List<CultureGraphQueryService.Relation>discover(@RequestParam(required=false)String countryCode,@RequestParam(required=false)String languageCode,@RequestParam(defaultValue="50")int limit){return query.discover(countryCode,languageCode,limit);}
 @PostMapping("/admin/culture-graph/rebuild")@ResponseStatus(HttpStatus.ACCEPTED)public Map<String,Object>rebuild(Authentication a){UUID id=rebuild.start(a.getName());return Map.of("jobId",id,"status","PENDING");}}
